const getQuestion = `-- name: GetQuestion :one
SELECT q.id, q.user_id, q.title, q.body, q.answer, q.answered_at, q.created_at,
       u.name AS user_name,
       COALESCE(a.name, '') AS answered_by_name,
       q.topic_id, COALESCE(t.name, '') AS topic_name, COALESCE(t.slug, '') AS topic_slug,
       q.answer_video_id, q.answer_seconds, q.live_event_id,
       COALESCE(av.title, '') AS video_title, COALESCE(av.embed_url, '') AS video_embed_url,
       COALESCE(av.url, '') AS video_url, COALESCE(av.vertical, 0) AS video_vertical,
       COALESCE(av.thumb_url, '') AS video_thumb_url,
       (SELECT COUNT(*) FROM question_votes v WHERE v.question_id = q.id) AS votes,
       EXISTS (SELECT 1 FROM question_votes v WHERE v.question_id = q.id AND v.user_id = ?1) AS voted
FROM questions q
JOIN users u ON u.id = q.user_id
LEFT JOIN users a ON a.id = q.answered_by
LEFT JOIN topics t ON t.id = q.topic_id
LEFT JOIN videos av ON av.id = q.answer_video_id
WHERE q.id = ?2 AND q.hidden = 0
`

type GetQuestionParams struct {
	Viewer int64
	ID     int64
}

type GetQuestionRow struct {
	ID             int64
	UserID         int64
	Title          string
	Body           string
	Answer         string
	AnsweredAt     sql.NullString
	CreatedAt      string
	UserName       string
	AnsweredByName string
	TopicID        sql.NullInt64
	TopicName      string
	TopicSlug      string
	AnswerVideoID  sql.NullInt64
	AnswerSeconds  int64
	LiveEventID    sql.NullInt64
	VideoTitle     string
	VideoEmbedUrl  string
	VideoUrl       string
	VideoVertical  int64
	VideoThumbUrl  string
	Votes          int64
	Voted          bool
}

func (q *Queries) GetQuestion(ctx context.Context, arg GetQuestionParams) (GetQuestionRow, error) {
	row := q.db.QueryRowContext(ctx, getQuestion, arg.Viewer, arg.ID)
	var i GetQuestionRow
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Title,
		&i.Body,
		&i.Answer,
		&i.AnsweredAt,
		&i.CreatedAt,
		&i.UserName,
		&i.AnsweredByName,
		&i.TopicID,
		&i.TopicName,
		&i.TopicSlug,
		&i.AnswerVideoID,
		&i.AnswerSeconds,
		&i.LiveEventID,
		&i.VideoTitle,
		&i.VideoEmbedUrl,
		&i.VideoUrl,
		&i.VideoVertical,
		&i.VideoThumbUrl,
		&i.Votes,
		&i.Voted,
	)
	return i, err
}

